import React, { useState } from 'react'

export default function FeatureSection({ id, title, description, importMsg, demo, code }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500); // reset after 1.5s
    });
  };
    return (
        <section id={id} className="ulsp-feature-section pdy8">
          <h3 className="font-semibold mgb2">
            {title} <a href={"#"+id} className='pointer' id={id}>#</a>
          </h3>
          
          {description && <div className="mgb8 " style={{ lineHeight: '1.5' }}>{description}</div>}

          {importMsg &&
            <div className='pd8 rds3 relative' style={{ backgroundColor: 'rgb(45, 45, 45)', color: 'rgb(204, 204, 204)' }}>
              {importMsg}
              <button
                className='absolute'
                style={{ top: '1rem', right: '1rem' }}
                onClick={() => handleCopy(importMsg)}
                title="Copy"
              >
                <i className='pi pi-copy'></i>
              </button>
              {copied && <span className="copied-msg absolute" style={{ top: '1rem', right: '3rem' }}>Copied!</span>}
            </div>
          }
          
          <div className="demo-and-code">
            <div className="demo ">
              {demo}
            </div>
          </div>
        </section>
    )
}
